"""Calendar boundaries, duration measurement and sparse time series."""
from _draft_helpers import topic

S = """
CREATE TABLE usage(d TEXT PRIMARY KEY,qty INTEGER);
INSERT INTO usage VALUES('2026-02-01',2),('2026-02-03',6),('2026-03-01',9);
CREATE TABLE appointment(id INTEGER PRIMARY KEY,started TEXT,ended TEXT);
INSERT INTO appointment VALUES
 (1,'2026-01-31 23:30:00','2026-02-01 00:15:00'),
 (2,'2026-02-01 00:00:00','2026-02-01 01:30:00'),
 (3,'2026-02-28 23:00:00','2026-03-01 01:00:00');
CREATE TABLE due(id INTEGER PRIMARY KEY,d TEXT);
INSERT INTO due VALUES(1,'2024-01-31'),(2,'2024-02-29'),(3,'2026-12-31');
"""
def T(n,slug,title,concepts,explain,q,out,p,a,b):
    return topic(n,slug,title,"temporal",concepts,explain,S,q,out,p,a,b)

LESSONS = [
 T(142,"half-open-month","半开时间区间避免月末漏数",["半开区间","时间边界","索引友好"],
   "月报用 d>=月初 AND d<下月月初，完整覆盖当月而无需猜测最后一秒。二月两笔用量 2+6=8，三月一日的 9 被排除。比较要求统一的 ISO 日期文本，实际时间戳还应统一时区。",
   "SELECT sum(qty) FROM usage WHERE d>='2026-02-01' AND d<'2026-03-01';","8",
   ["BETWEEN 同时包含上下端点，可能把下月首日计入。","混用本地时区与 UTC 会移动边界。"],
   ("列出二月明细日期。","保留同一半开区间。","SELECT d FROM usage WHERE d>='2026-02-01' AND d<'2026-03-01' ORDER BY d;","2026-02-01\n2026-02-03"),
   ("统计三月用量。","下界三月一日，上界四月一日。","SELECT sum(qty) FROM usage WHERE d>='2026-03-01' AND d<'2026-04-01';","9")),
 T(143,"elapsed-seconds","跨日任务按 Unix 秒计算耗时",["UNIXEPOCH","持续时间","跨日"],
   "结束秒数减开始秒数再除以 60，避免直接截取时分造成跨日负值。三个任务耗时依次 45、90、120 分钟。使用无小数秒的固定 ISO 时间，本课不把日历月份当作固定秒数。",
   "SELECT id,(unixepoch(ended)-unixepoch(started))/60 FROM appointment ORDER BY id;","1|45\n2|90\n3|120",
   ["月份和年份长度不固定，不能用固定秒数表示。","缺少时区约定时，夏令时可能影响业务含义。"],
   ("计算全部任务耗时分钟数。","先计算每行差，再 SUM。","SELECT sum(unixepoch(ended)-unixepoch(started))/60 FROM appointment;","255"),
   ("找出至少耗时两小时的任务。","直接比较秒差和 7200。","SELECT id FROM appointment WHERE unixepoch(ended)-unixepoch(started)>=7200 ORDER BY id;","3")),
 T(144,"calendar-month-floor","月底续费用 floor 解决月份歧义",["日期修饰符","floor","日历运算"],
   "日期加一个月可能不存在同号日期，floor 将歧义落在目标月最后一天。2024-01-31 续至闰年二月 29 日，二月 29 日续至三月 29 日，十二月跨到下一年。修饰符顺序决定 floor 处理哪一步。",
   "SELECT id,date(d,'+1 month','floor') FROM due ORDER BY id;","1|2024-02-29\n2|2024-03-29\n3|2027-01-31",
   ["SQLite 默认歧义处理不能替代产品明确的月底规则。","floor 必须紧跟导致歧义的位移。"],
   ("计算闰日一年后的 floor 日期。","给 2024-02-29 加一年再 floor。","SELECT date(d,'+1 year','floor') FROM due WHERE id=2;","2025-02-28"),
   ("仅列出续费月份跨年的记录 id。","比较加月前后的年份。","SELECT id FROM due WHERE strftime('%Y',d)<>strftime('%Y',date(d,'+1 month','floor')) ORDER BY id;","3")),
 T(145,"month-end-length","从月初推导月末与月天数",["start of month","月末","闰年"],
   "先退到月初，再加一个月减一天，得到稳定的月末。月末的日号就是当月天数，所以一月 31 天、闰年二月 29 天、十二月 31 天。此法不依赖手写月份天数字典。",
   "SELECT id,date(d,'start of month','+1 month','-1 day'),CAST(strftime('%d',date(d,'start of month','+1 month','-1 day')) AS INTEGER) FROM due ORDER BY id;","1|2024-01-31|31\n2|2024-02-29|29\n3|2026-12-31|31",
   ["先加月再退月初会受到月底歧义影响。","日号文本转数值后才能可靠参与计算。"],
   ("输出每个日期所在月的月初。","start of month 不改变年份月份。","SELECT id,date(d,'start of month') FROM due ORDER BY id;","1|2024-01-01\n2|2024-02-01\n3|2026-12-01"),
   ("找出正好处于月末的记录数。","原日期与推导月末比较。","SELECT count(*) FROM due WHERE d=date(d,'start of month','+1 month','-1 day');","3")),
 T(146,"iso-week-year","ISO 周年与日历年份并不相同",["%G","%V","ISO 周"],
   "ISO 周从周一开始，包含年初周四的一周属于新周年。2026-12-31 和 2027-01-01 都属于 2026 的第 53 周；用日历年份拼周号会错误拆成两组。周报应同时存周年和周号。",
   "WITH dates(d) AS(VALUES('2026-12-31'),('2027-01-01'),('2027-01-04')) SELECT d,strftime('%G-W%V',d) FROM dates ORDER BY d;","2026-12-31|2026-W53\n2027-01-01|2026-W53\n2027-01-04|2027-W01",
   ["%Y 是日历年，不能与 ISO %V 随意拼接。","ISO 格式符需要支持它们的 SQLite 版本。"],
   ("求十二月末日期的 ISO 周年。","使用 %G。","SELECT strftime('%G',d) FROM due WHERE id=3;","2026"),
   ("把三笔用量按 ISO 周汇总。","按周年周号分组。","SELECT strftime('%G-W%V',d),sum(qty) FROM usage GROUP BY 1 ORDER BY 1;","2026-W05|2\n2026-W06|6\n2026-W09|9")),
 T(147,"monday-week-bucket","将任意日期归到周一桶",["weekday","周桶","日期归一"],
   "weekday 0 向前到周日，再减六天得到所在周的周一。星期日 2026-02-01 归到 01-26，星期二 02-03 归到 02-02。桶键采用完整日期，跨年排序也不需要特殊处理。",
   "SELECT d,date(d,'weekday 0','-6 days') FROM usage ORDER BY d;","2026-02-01|2026-01-26\n2026-02-03|2026-02-02\n2026-03-01|2026-02-23",
   ["weekday 是向前寻找，而非向最近星期移动。","一周起点必须与产品规则一致。"],
   ("列出用量的星期日编号。","%w 中周日为 0。","SELECT d,strftime('%w',d) FROM usage ORDER BY d;","2026-02-01|0\n2026-02-03|2\n2026-03-01|0"),
   ("统计发生在周末的用量总数。","星期编号在 0、6 之内。","SELECT sum(qty) FROM usage WHERE strftime('%w',d) IN('0','6');","11")),
 T(148,"calendar-gap-fill","补齐缺失日期形成连续用量序列",["递归日历","LEFT JOIN","补零"],
   "递归 CTE 生成二月一日至四日，再左连稀疏用量。没有记录的二日和四日显示 0，而不是消失；日历充当结果粒度的主表。展示补零并不代表真实观测值就是零，业务应区分缺报和无用量。",
   "WITH RECURSIVE cal(d) AS(VALUES('2026-02-01') UNION ALL SELECT date(d,'+1 day') FROM cal WHERE d<'2026-02-04') SELECT cal.d,coalesce(u.qty,0) FROM cal LEFT JOIN usage u USING(d) ORDER BY cal.d;","2026-02-01|2\n2026-02-02|0\n2026-02-03|6\n2026-02-04|0",
   ["递归必须有有限上界。","真实表若同日多行，连接前要先聚合。"],
   ("只返回二月一日至四日没有记录的日期。","日历左连后检查用量主键。","WITH RECURSIVE cal(d) AS(VALUES('2026-02-01') UNION ALL SELECT date(d,'+1 day') FROM cal WHERE d<'2026-02-04') SELECT cal.d FROM cal LEFT JOIN usage u USING(d) WHERE u.d IS NULL ORDER BY cal.d;","2026-02-02\n2026-02-04"),
   ("按含缺报日的四天分母计算日均用量。","合计除以固定的四天。","SELECT sum(qty)/4.0 FROM usage WHERE d>='2026-02-01' AND d<'2026-02-05';","2.0")),
 T(149,"business-day-calendar","工作日日历排除周末与节假日",["递归 CTE","NOT EXISTS","工作日"],
   "日历列举 2026-02-02 至 02-08，再排除周六日和示例假日 02-04，剩余周一、周二、周四、周五。周末规则与假日表分别维护，避免仅凭星期判断把法定假日当工作日。",
   "WITH RECURSIVE cal(d) AS(VALUES('2026-02-02') UNION ALL SELECT date(d,'+1 day') FROM cal WHERE d<'2026-02-08'),holiday(d) AS(VALUES('2026-02-04')) SELECT d FROM cal WHERE strftime('%w',d) NOT IN('0','6') AND NOT EXISTS(SELECT 1 FROM holiday h WHERE h.d=cal.d) ORDER BY d;","2026-02-02\n2026-02-03\n2026-02-05\n2026-02-06",
   ["实际地区可能有调休工作周末，需完整日历表。","示例假日仅为练习数据，不是现实日历声明。"],
   ("统计该七天区间的普通周末天数。","使用 %w。","WITH RECURSIVE cal(d) AS(VALUES('2026-02-02') UNION ALL SELECT date(d,'+1 day') FROM cal WHERE d<'2026-02-08') SELECT count(*) FROM cal WHERE strftime('%w',d) IN('0','6');","2"),
   ("求二月三日之后的下一个星期一。","weekday 1 可能保留本日本周一。","SELECT date('2026-02-03','weekday 1');","2026-02-09")),
 T(150,"ageing-date-buckets","固定截至日的账龄分桶",["JULIANDAY","账龄","可复现"],
   "账龄使用固定截至日而不是 now，保证离线重跑可复现。二月一日和三日距二月五日为 4、2 天，三月一日尚在未来，归为 future。先处理负差，再按阈值分桶，避免未来账单落入逾期。",
   "SELECT d,CASE WHEN d>'2026-02-05' THEN 'future' WHEN julianday('2026-02-05')-julianday(d)<=2 THEN '0-2' ELSE '3+' END FROM usage ORDER BY d;","2026-02-01|3+\n2026-02-03|0-2\n2026-03-01|future",
   ["now 会使预期输出随日期漂移。","含时间部分时应明确按整天还是实际时长计算。"],
   ("求截至二月五日已发生用量的最早账龄天数。","MIN 日期对应最大账龄。","SELECT CAST(julianday('2026-02-05')-julianday(min(d)) AS INTEGER) FROM usage WHERE d<='2026-02-05';","4"),
   ("统计截至日之后的用量。","严格大于截至日。","SELECT sum(qty) FROM usage WHERE d>'2026-02-05';","9")),
 T(151,"fixed-timezone-normalization","带偏移时间统一为 UTC",["时区偏移","DATETIME","规范时间"],
   "SQLite 日期函数识别 ISO 时间中的数值偏移，并转换为 UTC。08:30+08:00 对应 00:30Z，前一日 19:30-05:00 也是同一时刻。比较统一时间后才能判断同时发生，不能直接比较原始文本。",
   "WITH stamp(id,t) AS(VALUES(1,'2026-02-01T08:30:00+08:00'),(2,'2026-01-31T19:30:00-05:00')) SELECT id,datetime(t) FROM stamp ORDER BY id;","1|2026-02-01 00:30:00\n2|2026-02-01 00:30:00",
   ["固定偏移不能表达某地区完整夏令时规则。","不要依赖设备 localtime 生成固定测试结果。"],
   ("把 UTC 午夜加八小时作为固定偏移展示。","展示转换与存储 UTC 分开。","SELECT datetime('2026-02-01 00:00:00','+8 hours');","2026-02-01 08:00:00"),
   ("验证两种时间表示的 Unix 秒一致。","分别转 UNIXEPOCH 后比较。","SELECT unixepoch('2026-02-01T08:30:00+08:00')=unixepoch('2026-02-01T00:30:00Z');","1")),
 T(152,"duration-vs-calendar-diff","日历差与实际经过天数分开计算",["TIMEDIFF","日历差","经过天数"],
   "二月与三月的同号日期可能相隔不同天数。2024-02-01 到 03-01 经历 29 天，03-01 到 04-01 经历 31 天；两者日历差均可描述为一个月。计费按天时应使用 JULIANDAY 差而不是把月份换成 30 天。",
   "SELECT CAST(julianday('2024-03-01')-julianday('2024-02-01') AS INTEGER),CAST(julianday('2024-04-01')-julianday('2024-03-01') AS INTEGER);","29|31",
   ["TIMEDIFF 的日历表达不是固定秒数。","计费规则需要明确是否包含起止日。"],
   ("输出闰年二月至三月的日历差。","TIMEDIFF 的参数顺序为终点、起点。","SELECT timediff('2024-03-01','2024-02-01');","+0000-01-00 00:00:00.000"),
   ("计算两段合计经过天数。","直接用最末日减最初日。","SELECT CAST(julianday('2024-04-01')-julianday('2024-02-01') AS INTEGER);","60")),
 T(153,"rolling-calendar-window","按日历天回看而不是按记录数回看",["范围连接","稀疏序列","滚动窗口"],
   "每个观察日回看当天和前两天，以日期范围相关聚合实现。二月三日包括一日的 2 和三日的 6，得到 8；三月一日只能包含自己的 9。稀疏数据上 ROWS 2 PRECEDING 会跨越大量缺失天，含义不同。",
   "SELECT a.d,(SELECT sum(b.qty) FROM usage b WHERE b.d>=date(a.d,'-2 days') AND b.d<=a.d) FROM usage a ORDER BY a.d;","2026-02-01|2\n2026-02-03|8\n2026-03-01|9",
   ["物理行窗口不是日历天窗口。","大表范围查询应给日期列建立索引。"],
   ("计算每个观察日前一天的用量，没有记录补零。","匹配 date(a.d,'-1 day')。","SELECT a.d,coalesce((SELECT b.qty FROM usage b WHERE b.d=date(a.d,'-1 day')),0) FROM usage a ORDER BY a.d;","2026-02-01|0\n2026-02-03|0\n2026-03-01|0"),
   ("找出前两天还存在其他观察记录的日期。","EXISTS 排除当前日。","SELECT a.d FROM usage a WHERE EXISTS(SELECT 1 FROM usage b WHERE b.d>=date(a.d,'-2 days') AND b.d<a.d) ORDER BY a.d;","2026-02-03")),
 T(154,"period-clipping","把跨月任务裁剪到报表月份",["MIN","MAX","区间裁剪"],
   "跨边界任务只计落在二月半开区间中的部分。任务 1 计午夜后 15 分钟，任务 2 计 90 分钟，任务 3 计三月前 60 分钟。用标量 MAX 取较晚起点、MIN 取较早终点，再计算秒差。",
   "SELECT id,(unixepoch(min(ended,'2026-03-01 00:00:00'))-unixepoch(max(started,'2026-02-01 00:00:00')))/60 FROM appointment WHERE started<'2026-03-01 00:00:00' AND ended>'2026-02-01 00:00:00' ORDER BY id;","1|15\n2|90\n3|60",
   ["应先判断区间相交，否则可能得到负时长。","端点相接时相交时长为零，不应当作正时长任务。"],
   ("统计二月份被任务占用的总分钟数，按任务计。","使用相同裁剪表达式再 SUM。","SELECT sum(unixepoch(min(ended,'2026-03-01 00:00:00'))-unixepoch(max(started,'2026-02-01 00:00:00')))/60 FROM appointment WHERE started<'2026-03-01 00:00:00' AND ended>'2026-02-01 00:00:00';","165"),
   ("只返回跨越月末零点的任务。","开始在边界前且结束在边界后。","SELECT id FROM appointment WHERE started<'2026-03-01 00:00:00' AND ended>'2026-03-01 00:00:00' ORDER BY id;","3")),
 T(155,"date-validation-roundtrip","日期文本通过规范化往返检查",["日期校验","往返","格式约束"],
   "YYYY-MM-DD 的文本形状不保证日期存在。先要求固定形状，再用 date(x,'+0 days') 规范化并比较原值，能识别 2026-02-30 被移动到三月。NULL 与非日期文本也显式判为失败；这是本课固定格式的校验策略。",
   "WITH raw(id,d) AS(VALUES(1,'2026-02-28'),(2,'2026-02-30'),(3,'bad'),(4,NULL)) SELECT id,coalesce(d GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(d,'+0 days')=d,0) FROM raw ORDER BY id;","1|1\n2|0\n3|0\n4|0",
   ["仅 GLOB 只能验证形状，不能验证日历。","校验策略应约束支持的年份范围与输入格式。"],
   ("验证闰年的二月二十九日能够往返。","固定日期加零天。","SELECT date('2024-02-29','+0 days')='2024-02-29';","1"),
   ("输出无效二月三十日规范化后的日期。","date 加零天触发规范化。","SELECT date('2026-02-30','+0 days');","2026-03-02")),
 T(156,"effective-dated-lookup","按事件时间匹配生效版本",["有效期","半开区间","历史维度"],
   "价格版本用 [from,to) 保存，事件按其日期匹配当时版本。一月有效价格 10，二月起价格 12，因此三笔用量都匹配 12。NULL 上界表示持续有效；边界日只归到新版本，避免双重匹配。",
   "WITH price(valid_from,valid_to,unit) AS(VALUES('2026-01-01','2026-02-01',10),('2026-02-01',NULL,12)) SELECT u.d,u.qty,p.unit FROM usage u JOIN price p ON u.d>=p.valid_from AND (u.d<p.valid_to OR p.valid_to IS NULL) ORDER BY u.d;","2026-02-01|2|12\n2026-02-03|6|12\n2026-03-01|9|12",
   ["版本区间重叠会把事件复制为多行。","不要用当前价格重算历史交易。"],
   ("计算按历史有效价核算的总费用。","将用量乘匹配版本单价。","WITH price(a,b,v) AS(VALUES('2026-01-01','2026-02-01',10),('2026-02-01',NULL,12)) SELECT sum(u.qty*p.v) FROM usage u JOIN price p ON u.d>=p.a AND (u.d<p.b OR p.b IS NULL);","204"),
   ("找出二月一日的生效价格。","上界排他，NULL 表示无限期。","WITH price(a,b,v) AS(VALUES('2026-01-01','2026-02-01',10),('2026-02-01',NULL,12)) SELECT v FROM price WHERE '2026-02-01'>=a AND ('2026-02-01'<b OR b IS NULL);","12")),
]
